CREATE OR REPLACE FUNCTION rescue_outbox() RETURNS trigger AS $$ DECLARE eid uuid:=gen_random_uuid();et text;rk text;BEGIN et:=CASE WHEN TG_OP='INSERT' THEN 'RescueRegistrationCreated' WHEN NEW.status='APPROVED' THEN 'RescueRegistrationApproved' ELSE 'RescueRegistrationRejected' END;rk:=CASE et WHEN 'RescueRegistrationCreated' THEN 'rescue.registration.created' WHEN 'RescueRegistrationApproved' THEN 'rescue.registration.approved' ELSE 'rescue.registration.rejected' END;INSERT INTO outbox_events(id,aggregate_type,aggregate_id,event_type,event_version,payload,status,created_at)VALUES(eid,'RescueRegistration',NEW.id::text,et,1,jsonb_build_object('eventId',eid,'eventType',et,'eventVersion',1,'aggregateType','RescueRegistration','aggregateId',NEW.id::text,'occurredAt',now(),'traceId',gen_random_uuid(),'producer','rescue-service','routingKey',rk,'payload',jsonb_build_object('registrationId',NEW.id,'cropBatchId',NEW.crop_batch_id,'farmerId',NEW.farmer_id,'rescuePointId',NEW.rescue_point_id,'status',NEW.status)),'PENDING',now());RETURN NEW;END$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_rescue_outbox AFTER INSERT OR UPDATE OF status ON rescue_registrations FOR EACH ROW EXECUTE FUNCTION rescue_outbox();
